-- Sprint 4 account and read-only wallet foundation (PostgreSQL)
CREATE TYPE "AccountStatus" AS ENUM ('PENDING_VERIFICATION','ACTIVE','RESTRICTED','SUSPENDED','CLOSED');
CREATE TYPE "SyncStatus" AS ENUM ('PENDING','SYNCING','CURRENT','DELAYED','FAILED');
CREATE TYPE "AssetType" AS ENUM ('NATIVE','ERC20');
CREATE TYPE "TransactionStatus" AS ENUM ('PENDING','CONFIRMED','FAILED','REPLACED','UNKNOWN');
CREATE TYPE "TransactionDirection" AS ENUM ('INCOMING','OUTGOING','SELF','CONTRACT_INTERACTION');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"emailVerifiedAt" TIMESTAMP(3),"passwordHash" TEXT NOT NULL,"accountStatus" "AccountStatus" NOT NULL DEFAULT 'PENDING_VERIFICATION',"termsAcceptedAt" TIMESTAMP(3) NOT NULL,"privacyAcceptedAt" TIMESTAMP(3) NOT NULL,"odcDisclaimerAcceptedAt" TIMESTAMP(3) NOT NULL,"walletDisclosureAcceptedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastLoginAt" TIMESTAMP(3));
CREATE TABLE "UserProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,"displayName" TEXT NOT NULL,"firstName" TEXT,"lastName" TEXT,"username" TEXT UNIQUE,"avatarUrl" TEXT,"countryCode" TEXT,"timezone" TEXT,"profileVisibility" TEXT NOT NULL DEFAULT 'PRIVATE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"sessionTokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"expires" TIMESTAMP(3) NOT NULL,"rememberMe" BOOLEAN NOT NULL DEFAULT false,"revokedAt" TIMESTAMP(3));
CREATE TABLE "VerificationToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"expires" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PasswordResetToken" (LIKE "VerificationToken" INCLUDING ALL);
CREATE TABLE "Wallet" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id"),"address" TEXT NOT NULL,"normalizedAddress" TEXT NOT NULL,"chainId" INTEGER NOT NULL,"network" TEXT NOT NULL,"walletType" TEXT,"label" TEXT,"isPrimary" BOOLEAN NOT NULL DEFAULT false,"verificationMethod" TEXT NOT NULL DEFAULT 'SIWE',"verifiedAt" TIMESTAMP(3) NOT NULL,"lastSyncedAt" TIMESTAMP(3),"syncStatus" "SyncStatus" NOT NULL DEFAULT 'PENDING',"syncError" TEXT,"disconnectedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("normalizedAddress","chainId","disconnectedAt"));
CREATE TABLE "WalletChallenge" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"walletId" TEXT REFERENCES "Wallet"("id"),"address" TEXT NOT NULL,"nonceHash" TEXT NOT NULL UNIQUE,"message" TEXT NOT NULL,"domain" TEXT NOT NULL,"chainId" INTEGER NOT NULL,"issuedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3));
CREATE TABLE "WalletBalance" ("id" TEXT PRIMARY KEY,"walletId" TEXT NOT NULL REFERENCES "Wallet"("id"),"assetType" "AssetType" NOT NULL,"contractAddress" TEXT,"symbol" TEXT NOT NULL,"decimals" INTEGER NOT NULL,"rawBalance" TEXT NOT NULL,"formattedBalance" TEXT NOT NULL,"blockNumber" BIGINT NOT NULL,"sourceProvider" TEXT NOT NULL,"retrievedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("walletId","assetType","contractAddress"));
CREATE TABLE "BlockchainTransaction" ("id" TEXT PRIMARY KEY,"walletId" TEXT NOT NULL REFERENCES "Wallet"("id"),"chainId" INTEGER NOT NULL,"network" TEXT NOT NULL,"transactionHash" TEXT NOT NULL,"logIndex" INTEGER NOT NULL DEFAULT -1,"blockNumber" BIGINT,"blockTimestamp" TIMESTAMP(3),"transactionIndex" INTEGER,"assetType" "AssetType" NOT NULL,"contractAddress" TEXT,"eventType" TEXT NOT NULL,"direction" "TransactionDirection" NOT NULL,"fromAddress" TEXT NOT NULL,"toAddress" TEXT,"rawAmount" TEXT,"formattedAmount" TEXT,"symbol" TEXT,"decimals" INTEGER,"status" "TransactionStatus" NOT NULL,"gasUsed" TEXT,"gasPrice" TEXT,"transactionFee" TEXT,"confirmationCount" INTEGER NOT NULL DEFAULT 0,"sourceProvider" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("chainId","transactionHash","logIndex","walletId"));
CREATE TABLE "DisclosureDocument" ("id" TEXT PRIMARY KEY,"documentType" TEXT NOT NULL,"version" TEXT NOT NULL,"documentHash" TEXT NOT NULL,"content" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("documentType","version"));
CREATE TABLE "DisclosureAcceptance" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id"),"walletId" TEXT REFERENCES "Wallet"("id"),"documentId" TEXT NOT NULL REFERENCES "DisclosureDocument"("id"),"documentVersion" TEXT NOT NULL,"documentHash" TEXT NOT NULL,"acceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ipAddressHash" TEXT,"userAgentHash" TEXT,"source" TEXT NOT NULL,UNIQUE("userId","documentId","documentVersion"));
CREATE TABLE "SecurityEvent" ("id" TEXT PRIMARY KEY,"userId" TEXT REFERENCES "User"("id"),"eventType" TEXT NOT NULL,"outcome" TEXT NOT NULL,"ipAddressHash" TEXT,"userAgentHash" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"userId" TEXT REFERENCES "User"("id"),"actorType" TEXT NOT NULL,"action" TEXT NOT NULL,"resourceType" TEXT,"resourceId" TEXT,"metadata" JSONB,"integrityHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Wallet_userId_idx" ON "Wallet"("userId"); CREATE INDEX "Wallet_normalizedAddress_idx" ON "Wallet"("normalizedAddress");
CREATE INDEX "Transaction_hash_idx" ON "BlockchainTransaction"("transactionHash"); CREATE INDEX "Transaction_wallet_block_idx" ON "BlockchainTransaction"("walletId","blockNumber"); CREATE INDEX "Transaction_wallet_time_idx" ON "BlockchainTransaction"("walletId","blockTimestamp"); CREATE INDEX "Transaction_contract_idx" ON "BlockchainTransaction"("contractAddress");
CREATE INDEX "SecurityEvent_user_time_idx" ON "SecurityEvent"("userId","createdAt"); CREATE INDEX "Disclosure_user_version_idx" ON "DisclosureAcceptance"("userId","documentVersion");
CREATE TABLE "Account" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerAccountId" TEXT NOT NULL,UNIQUE("provider","providerAccountId"));
CREATE TABLE "WalletSyncState" ("id" TEXT PRIMARY KEY,"walletId" TEXT NOT NULL UNIQUE REFERENCES "Wallet"("id"),"lastBalanceBlock" BIGINT,"lastTransactionBlock" BIGINT,"lastFinalizedBlock" BIGINT,"retryCount" INTEGER NOT NULL DEFAULT 0,"lastError" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
